namespace {

QVariantMap ok(const QVariantMap &value) { return {{QStringLiteral("ok"), value}}; }
QVariantMap cancelled() { return {{QStringLiteral("cancelled"), QVariantMap{}}}; }
QVariantMap failed(const QString &message)
{
    return {{QStringLiteral("failed"), QVariantMap{{QStringLiteral("message"), message}}}};
}

// The MIME types an app names, and the extensions a dialog filters on -- the
// same table, in the same order, as the Compose and SwiftUI libraries. A type
// this table does not know is dropped rather than failing the request.
const QList<QPair<QString, QStringList>> &mimeExtensions()
{
    static const QList<QPair<QString, QStringList>> table{
        {QStringLiteral("application/json"), {QStringLiteral("json")}},
        {QStringLiteral("text/plain"), {QStringLiteral("txt")}},
        {QStringLiteral("text/markdown"), {QStringLiteral("md"), QStringLiteral("markdown")}},
        {QStringLiteral("text/csv"), {QStringLiteral("csv")}},
        {QStringLiteral("application/pdf"), {QStringLiteral("pdf")}},
        {QStringLiteral("application/zip"), {QStringLiteral("zip")}},
        {QStringLiteral("image/jpeg"), {QStringLiteral("jpg"), QStringLiteral("jpeg")}},
        {QStringLiteral("image/png"), {QStringLiteral("png")}},
        {QStringLiteral("image/webp"), {QStringLiteral("webp")}},
        {QStringLiteral("image/gif"), {QStringLiteral("gif")}},
        {QStringLiteral("image/bmp"), {QStringLiteral("bmp")}},
        {QStringLiteral("image/tiff"), {QStringLiteral("tif"), QStringLiteral("tiff")}},
        {QStringLiteral("image/svg+xml"), {QStringLiteral("svg")}},
    };
    return table;
}

QString mimeTypeFor(const QString &fileName)
{
    const QString extension = QFileInfo(fileName).suffix().toLower();
    for (const auto &row : mimeExtensions()) {
        if (row.second.contains(extension)) {
            return row.first;
        }
    }
    return QStringLiteral("application/octet-stream");
}

QStringList extensionsFor(const QVariantMap &payload)
{
    QStringList out;
    for (const QVariant &accepted : payload.value(QStringLiteral("accept")).toList()) {
        if (accepted.typeId() != QMetaType::QString) {
            continue;
        }
        for (const auto &row : mimeExtensions()) {
            if (row.first == accepted.toString()) {
                for (const QString &extension : row.second) {
                    if (!out.contains(extension)) {
                        out.append(extension);
                    }
                }
            }
        }
    }
    return out;
}

// The extension after the last `.`, folded through upper case so `ſ` (LONG S)
// compares as `s`; empty when there is no dot.
QString fileExtension(const QString &name)
{
    const qsizetype dot = name.lastIndexOf(QLatin1Char('.'));
    return dot < 0 ? QString() : name.mid(dot + 1).toUpper().toLower();
}

// Characters that render as a wide blank without being whitespace: the Hangul
// fillers and BRAILLE PATTERN BLANK. Whitespace for the padding rules.
bool isBlank(char32_t point)
{
    return point == 0x115F || point == 0x1160 || point == 0x2800 || point == 0x3164
        || point == 0xFFA0;
}

bool isSpace(char32_t point) { return QChar::isSpace(point) || isBlank(point); }

// Unicode's Default_Ignorable_Code_Point, minus the blanks: variation
// selectors, COMBINING GRAPHEME JOINER and the like -- the same ranges as the
// Compose library. Dropped before the padding and dot rules.
bool isInvisible(char32_t p)
{
    if (isBlank(p)) {
        return false;
    }
    return p == 0x00AD || p == 0x034F || p == 0x061C || (p >= 0x115F && p <= 0x1160)
        || (p >= 0x17B4 && p <= 0x17B5) || (p >= 0x180B && p <= 0x180F)
        || (p >= 0x200B && p <= 0x200F) || (p >= 0x202A && p <= 0x202E)
        || (p >= 0x2060 && p <= 0x206F) || p == 0x3164 || (p >= 0xFE00 && p <= 0xFE0F)
        || p == 0xFEFF || p == 0xFFA0 || (p >= 0xFFF0 && p <= 0xFFF8)
        || (p >= 0x1BCA0 && p <= 0x1BCA3) || (p >= 0x1D173 && p <= 0x1D17A)
        || (p >= 0xE0000 && p <= 0xE0FFF);
}

// The code points of `name`, or no value when it holds a lone surrogate
// (which cannot be a file name). `QString::toUcs4` would quietly replace one.
std::optional<QList<char32_t>> codePoints(const QString &name)
{
    QList<char32_t> points;
    for (qsizetype i = 0; i < name.size(); ++i) {
        const QChar unit = name.at(i);
        if (unit.isHighSurrogate()) {
            if (i + 1 >= name.size() || !name.at(i + 1).isLowSurrogate()) {
                return std::nullopt;
            }
            points.append(QChar::surrogateToUcs4(unit, name.at(i + 1)));
            ++i;
        } else if (unit.isLowSurrogate()) {
            return std::nullopt;
        } else {
            points.append(unit.unicode());
        }
    }
    return points;
}

// Read at most `limit` bytes, bounded while reading. On Unix the chosen file
// is opened ONCE -- O_NONBLOCK so a FIFO swapped in cannot block the event
// loop, O_NOFOLLOW so a link swapped in after the dialog is not followed --
// and its type is taken from that descriptor, never from a second lookup.
enum class ReadOutcome { Ok, NotRegular, TooLarge, Unreadable };

ReadOutcome readChosenFile(const QString &path, qint64 limit, QByteArray *out)
{
#ifdef Q_OS_UNIX
    const QByteArray native = QFile::encodeName(QFileInfo(path).canonicalFilePath());
    if (native.isEmpty()) {
        return ReadOutcome::Unreadable;
    }
    const int descriptor = ::open(native.constData(), O_RDONLY | O_NONBLOCK | O_NOFOLLOW | O_CLOEXEC);
    if (descriptor < 0) {
        return ReadOutcome::Unreadable;
    }
    struct stat info {};
    if (::fstat(descriptor, &info) != 0) {
        ::close(descriptor);
        return ReadOutcome::Unreadable;
    }
    if (!S_ISREG(info.st_mode)) {
        ::close(descriptor);
        return ReadOutcome::NotRegular;
    }
    QFile file;
    if (!file.open(descriptor, QIODevice::ReadOnly, QFileDevice::AutoCloseHandle)) {
        ::close(descriptor);
        return ReadOutcome::Unreadable;
    }
#else
    if (!QFileInfo(path).isFile()) {
        return ReadOutcome::NotRegular;
    }
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
        return ReadOutcome::Unreadable;
    }
#endif
    out->clear();
    while (true) {
        const QByteArray chunk = file.read(64 * 1024);
        if (chunk.isEmpty()) {
            return file.error() == QFileDevice::NoError ? ReadOutcome::Ok : ReadOutcome::Unreadable;
        }
        if (out->size() + chunk.size() > limit) {
            return ReadOutcome::TooLarge;
        }
        out->append(chunk);
    }
}

// Write `bytes` beside `target` and rename it into place, so an interrupted
// save never leaves a half-written file where the person's old one was.
bool writeReplacing(const QString &target, const QByteArray &bytes)
{
#ifdef Q_OS_UNIX
    const QFileInfo targetInfo(target);
    const QByteArray targetNative = QFile::encodeName(targetInfo.absoluteFilePath());
    // The replaced file's rwx bits (never setuid, setgid or sticky), and only
    // from a regular file the person owns; a new file stays owner-only.
    mode_t mode = 0600;
    struct stat existing {};
    if (::lstat(targetNative.constData(), &existing) == 0 && S_ISREG(existing.st_mode)
        && existing.st_uid == ::getuid()) {
        mode = existing.st_mode & 0777;
    }
    const QString temporary = targetInfo.absolutePath() + QStringLiteral("/.mosaic-save-")
        + QUuid::createUuid().toString(QUuid::WithoutBraces) + QStringLiteral(".tmp");
    const QByteArray temporaryNative = QFile::encodeName(temporary);
    // O_EXCL: the temporary cannot be a link someone planted.
    const int descriptor = ::open(temporaryNative.constData(),
                                  O_WRONLY | O_CREAT | O_EXCL | O_NOFOLLOW | O_CLOEXEC, 0600);
    if (descriptor < 0) {
        return false;
    }
    qint64 written = 0;
    while (written < bytes.size()) {
        const ssize_t step = ::write(descriptor, bytes.constData() + written,
                                     static_cast<size_t>(bytes.size() - written));
        if (step < 0) {
            if (errno == EINTR) {
                continue;
            }
            break;
        }
        written += step;
    }
    // The mode goes on through the open descriptor: a chmod by path would
    // follow a symlink swapped in after the write.
    const bool complete = written == bytes.size() && ::fchmod(descriptor, mode) == 0
        && ::fsync(descriptor) == 0;
    ::close(descriptor);
    if (!complete || ::rename(temporaryNative.constData(), targetNative.constData()) != 0) {
        ::unlink(temporaryNative.constData());
        return false;
    }
    return true;
#else
    // Windows: QSaveFile writes beside the target and renames into place;
    // ACLs are inherited from the folder.
    QSaveFile file(target);
    if (!file.open(QIODevice::WriteOnly) || file.write(bytes) != bytes.size()) {
        file.cancelWriting();
        return false;
    }
    return file.commit();
#endif
}

#ifdef QT_WIDGETS_LIB
QString filterFor(const QStringList &extensions)
{
    if (extensions.isEmpty()) {
        return QString();
    }
    QStringList globs;
    for (const QString &extension : extensions) {
        globs.append(QStringLiteral("*.") + extension);
    }
    return QStringLiteral("Files (%1)").arg(globs.join(QLatin1Char(' ')));
}

class QtFileDialogs final : public MosaicFileDialogs
{
public:
    QString chooseFileToOpen(const QStringList &extensions) override
    {
        // Images only: open in Pictures, as a photo picker should. Anything
        // else -- and a Pictures folder this system does not have -- keeps
        // Qt's default start (an empty directory).
        QString start;
        if (mosaicOnlyImages(extensions)) {
            const QString pictures =
                QStandardPaths::writableLocation(QStandardPaths::PicturesLocation);
            if (!pictures.isEmpty() && QDir(pictures).exists()) {
                start = pictures;
            }
        }
        return QFileDialog::getOpenFileName(nullptr, QObject::tr("Open"), start,
                                            filterFor(extensions));
    }

    QString chooseFileToSave(const QString &suggestedName, const QStringList &extensions) override
    {
        return QFileDialog::getSaveFileName(nullptr, QObject::tr("Save"), suggestedName,
                                            filterFor(extensions));
    }
};
#endif

} // namespace

bool mosaicOnlyImages(const QStringList &extensions)
{
    if (extensions.isEmpty()) {
        return false;
    }
    for (const QString &extension : extensions) {
        bool image = false;
        for (const auto &row : mimeExtensions()) {
            if (row.first.startsWith(QStringLiteral("image/")) && row.second.contains(extension)) {
                image = true;
                break;
            }
        }
        if (!image) {
            return false;
        }
    }
    return true;
}

QSet<QString> mosaicStandardEffectKinds()
{
    return {QStringLiteral("files.open"), QStringLiteral("files.save")};
}

std::shared_ptr<MosaicFileDialogs> mosaicSystemFileDialogs()
{
#ifdef QT_WIDGETS_LIB
    return std::make_shared<QtFileDialogs>();
#else
    return nullptr;
#endif
}

std::optional<bool> mosaicRoutesToPlatform(const QString &kind,
                                           const std::optional<QSet<QString>> &appKinds)
{
    if (appKinds.has_value() && appKinds->contains(kind)) {
        return false;
    }
    if (mosaicStandardEffectKinds().contains(kind)) {
        return true;
    }
    if (!appKinds.has_value()) {
        return false;
    }
    return std::nullopt;
}

